package monosleep.data;

/**
 * Languages generated by {@link MonosleepLangProvider}, with every translatable string of the mod in
 * one place. {@link #RU_RU} is also the fallback text baked into the components the server sends, so
 * clients without this mod installed still see readable text.
 */
public enum MonosleepLang {
	EN_US("en_us", "Monosleep", "One sleep against the whole lobby, and it was enough to bring the morning", "%s went to bed"),
	RU_RU("ru_ru", "Моносон", "Один сон против целого онлайна — и этого хватило, чтобы наступило утро", "Игрок %s лёг спать");

	private final String code;
	private final String advancementTitle;
	private final String advancementDescription;
	private final String playerSlept;

	MonosleepLang(String code, String advancementTitle, String advancementDescription, String playerSlept) {
		this.code = code;
		this.advancementTitle = advancementTitle;
		this.advancementDescription = advancementDescription;
		this.playerSlept = playerSlept;
	}

	public String code() {
		return this.code;
	}

	public String advancementTitle() {
		return this.advancementTitle;
	}

	public String advancementDescription() {
		return this.advancementDescription;
	}

	public String playerSlept() {
		return this.playerSlept;
	}
}
